#pragma once
#include "pcs_adapter.hpp"
#include <map>
#include <set>
namespace pa {
static uint64_t online_payload=0;
inline double elapsed(std::chrono::steady_clock::time_point start){return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}
struct Transcript{Hash state;uint64_t count=0;explicit Transcript(const Bytes& b){Bytes init{'P','A','P','P','A','S','-','P','C','S','-','V','1'};init.insert(init.end(),b.begin(),b.end());state=digest(init);}void absorb(const char*tag,const Bytes& b){Bytes x;hash(x,state);u64(x,strlen(tag));x.insert(x.end(),tag,tag+strlen(tag));u64(x,b.size());x.insert(x.end(),b.begin(),b.end());state=digest(x);count=0;}Hash challenge(const char*tag){Bytes x;hash(x,state);u64(x,strlen(tag));x.insert(x.end(),tag,tag+strlen(tag));u64(x,count++);return digest(x);}F scalar(const char*tag){F x;uint64_t parts[2];for(auto p:{&parts[0],&parts[1]}){for(;;){auto h=challenge(tag);uint64_t z=0;for(int j=0;j<8;j++)z|=uint64_t(h[j])<<(8*j);z&=PRIME;if(z<PRIME){*p=z;break;}}}x.real=parts[0];x.img=parts[1];Bytes b;field(b,x);absorb(tag,b);return x;}};
inline Hash pair_hash(const Hash&a,const Hash&b){Bytes p;hash(p,a);hash(p,b);return digest(p);}
inline Hash leaf_salt(const Hash&seed,size_t index){Bytes b;u64(b,index);Hash salt;blake3_hasher h;blake3_hasher_init_keyed(&h,seed.data());blake3_hasher_update(&h,b.data(),b.size());blake3_hasher_finalize(&h,salt.data(),32);return salt;}
inline Hash salted_leaf(const Bytes&values,const Hash&salt){Bytes b{0};b.insert(b.end(),values.begin(),values.end());hash(b,salt);return digest(b);}
struct Tree{Hash seed;std::vector<std::vector<Hash>> levels;explicit Tree(const Vec&v):Tree(v,random_hash()){}Tree(const Vec&v,Hash key):seed(key){require(v.size()>=4&&!(v.size()%4),"leaf count");levels.emplace_back(v.size()/4);for(size_t i=0;i<v.size()/4;i++){Bytes b;for(size_t j=0;j<4;j++)field(b,v[4*i+j]);levels[0][i]=salted_leaf(b,leaf_salt(seed,i));}while(levels.back().size()>1){auto&old=levels.back();std::vector<Hash> next(old.size()/2);for(size_t i=0;i<next.size();i++)next[i]=pair_hash(old[2*i],old[2*i+1]);levels.push_back(std::move(next));}}Hash root()const{return levels.back()[0];}void open(Bytes&b,const Vec&v,size_t leaf)const{u64(b,leaf);for(size_t j=0;j<4;j++)field(b,v[4*leaf+j]);hash(b,leaf_salt(seed,leaf));for(size_t level=0;level+1<levels.size();level++){hash(b,levels[level][leaf^1]);leaf>>=1;}}};
struct Roots{std::vector<Hash> roots,nonces;size_t size()const{return roots.size();}const Hash&operator[](size_t i)const{return roots[i];}};
inline Bytes root_bytes(const Roots&r){Bytes b;for(size_t i=0;i<r.size();i++){hash(b,r.roots[i]);hash(b,r.nonces[i]);}return b;}
inline Roots read_roots(Reader&r,size_t n){Roots v;for(size_t i=0;i<n;i++){v.roots.push_back(r.digest());v.nonces.push_back(r.digest());}return v;}
inline Hash global_root(const Roots&r){std::vector<Hash> v(r.size());for(size_t i=0;i<r.size();i++)v[i]=pair_hash(r.roots[i],r.nonces[i]);while(v.size()>1){std::vector<Hash> t(v.size()/2);for(size_t i=0;i<t.size();i++)t[i]=pair_hash(v[2*i],v[2*i+1]);v=std::move(t);}return v[0];}
inline Bytes direct_allgather(const Bytes&b,size_t N,int rank){require(b.size()<INT32_MAX,"message size");Bytes all(N*b.size());std::copy(b.begin(),b.end(),all.begin()+rank*b.size());std::vector<MPI_Request> requests;requests.reserve(2*(N-1));for(size_t j=0;j<N;j++)if(j!=size_t(rank)){MPI_Request q;MPI_Irecv(all.data()+j*b.size(),b.size(),MPI_BYTE,j,101,MPI_COMM_WORLD,&q);requests.push_back(q);}for(size_t j=0;j<N;j++)if(j!=size_t(rank)){MPI_Request q;MPI_Isend(b.data(),b.size(),MPI_BYTE,j,101,MPI_COMM_WORLD,&q);requests.push_back(q);}MPI_Waitall(requests.size(),requests.data(),MPI_STATUSES_IGNORE);online_payload+=(N-1)*b.size();return all;}
inline Bytes direct_gather(const Bytes&b,size_t N,int rank){require(b.size()<INT32_MAX,"message size");Bytes all(rank==0?N*b.size():0);if(rank==0){std::copy(b.begin(),b.end(),all.begin());std::vector<MPI_Request> requests(N-1);for(size_t j=1;j<N;j++)MPI_Irecv(all.data()+j*b.size(),b.size(),MPI_BYTE,j,102,MPI_COMM_WORLD,&requests[j-1]);MPI_Waitall(requests.size(),requests.data(),MPI_STATUSES_IGNORE);}else{MPI_Send(b.data(),b.size(),MPI_BYTE,0,102,MPI_COMM_WORLD);online_payload+=b.size();}return all;}
inline void direct_broadcast(Bytes&b,size_t N,int rank){if(rank==0){std::vector<MPI_Request> requests(N-1);for(size_t j=1;j<N;j++)MPI_Isend(b.data(),b.size(),MPI_BYTE,j,103,MPI_COMM_WORLD,&requests[j-1]);MPI_Waitall(requests.size(),requests.data(),MPI_STATUSES_IGNORE);online_payload+=(N-1)*b.size();}else MPI_Recv(b.data(),b.size(),MPI_BYTE,0,103,MPI_COMM_WORLD,MPI_STATUS_IGNORE);}
inline Roots exchange_root(Hash local,size_t N){int rank;MPI_Comm_rank(MPI_COMM_WORLD,&rank);Bytes b;hash(b,local);hash(b,random_hash());auto all=direct_allgather(b,N,rank);Reader r{all};return read_roots(r,N);}
inline Vec encode_coeff(Vec c){c.resize(c.size()*4,F(0));fft(c,lg(c.size()),false);return c;}
inline void fold_vector(Vec&v,F a){for(size_t i=0;i<v.size()/2;i++)v[i]=v[2*i]+a*(v[2*i+1]-v[2*i]);v.resize(v.size()/2);}
inline F dot(const Vec&a,const Vec&b){require(a.size()==b.size(),"dot dimensions");F x=0;for(size_t i=0;i<a.size();i++)x+=a[i]*b[i];return x;}
struct Query{size_t party,pos;};
inline std::vector<Query> queries(Transcript&t,const Statement&s){std::vector<Query> q;for(size_t i=0;i<Q;i++){auto h=t.challenge("query");uint64_t a=0,b=0;for(int j=0;j<8;j++){a|=uint64_t(h[j])<<(8*j);b|=uint64_t(h[8+j])<<(8*j);}q.push_back({size_t(a&(s.N-1)),size_t(b&(4*s.D-1))});}return q;}
inline std::set<size_t> query_leaves(const std::vector<Query>&q,size_t rank,size_t size){std::set<size_t> r;for(auto x:q)if(x.party==rank){size_t lo=x.pos%(size/2);r.insert(lo/4);r.insert((lo+size/2)/4);}return r;}
inline void open_leaves(Bytes&b,const Vec&v,const Tree&t,const std::set<size_t>&leaves){for(auto j:leaves)t.open(b,v,j);}
inline std::map<size_t,std::array<F,4>> authenticate(Reader&r,size_t size,Hash root,const std::set<size_t>&leaves){std::map<size_t,std::array<F,4>> out;for(auto expected:leaves){size_t leaf=r.number();require(leaf==expected,"query leaf index");Bytes b;std::array<F,4> values;for(auto&x:values){x=r.value();field(b,x);}Hash salt=r.digest();Hash h=salted_leaf(b,salt);size_t index=leaf;for(size_t l=0;l<lg(size/4);l++){Hash sib=r.digest();h=(index&1)?pair_hash(sib,h):pair_hash(h,sib);index>>=1;}require(h==root,"Merkle authentication");out.emplace(leaf,values);}return out;}
inline Bytes gather_bytes(const Bytes&local,size_t N,int rank){require(local.size()<INT32_MAX,"proof chunk too large");Bytes sizebuf;u64(sizebuf,local.size());auto sizes=direct_gather(sizebuf,N,rank);Bytes out;if(rank==0){Reader r{sizes};for(size_t i=0;i<N;i++){size_t len=r.number();require(len<INT32_MAX,"proof chunk too large");u64(out,len);if(i==0)out.insert(out.end(),local.begin(),local.end());else{Bytes b(len);MPI_Recv(b.data(),b.size(),MPI_BYTE,i,321,MPI_COMM_WORLD,MPI_STATUS_IGNORE);out.insert(out.end(),b.begin(),b.end());}}}else{MPI_Send(local.data(),local.size(),MPI_BYTE,0,321,MPI_COMM_WORLD);online_payload+=local.size();}return out;}
inline std::vector<Vec> exchange_tail(const Vec&local,const Statement&s,int rank,Hash seed,std::vector<Hash>&seeds){Bytes b;hash(b,seed);fields(b,local);Bytes all=direct_gather(b,s.N,rank);std::vector<Vec> tails;if(rank==0){Reader r{all};for(size_t i=0;i<s.N;i++){seeds.push_back(r.digest());tails.push_back(r.values(local.size()));}r.end();}return tails;}
inline Bytes tails_bytes(const std::vector<Vec>&tails,const std::vector<Hash>&seeds){Bytes b;for(size_t i=0;i<tails.size();i++){hash(b,seeds[i]);fields(b,tails[i]);}return b;}
inline void check_terminal(const Statement&s,const std::vector<Vec>&tails,const Roots&roots,const std::vector<Hash>&seeds,const Vec&weights,F y){size_t d=s.D>>s.R;require(weights.size()==d,"terminal weight dimension");std::vector<Vec> coeff(s.N);for(size_t i=0;i<s.N;i++){require(tails[i].size()==4*d,"terminal dimension");require(Tree(tails[i],seeds[i]).root()==roots[i],"terminal root");coeff[i]=tails[i];fft(coeff[i],lg(4*d),true);for(size_t j=d;j<4*d;j++)require(coeff[i][j]==F(0),"terminal row degree");coeff[i].resize(d);}Vec cw=column_weights(s);F value=0;for(size_t j=0;j<d;j++){Vec column(s.N);for(size_t i=0;i<s.N;i++)column[i]=coeff[i][j];auto decoded=recover(column,s.kp);for(size_t i=0;i<s.k;i++)value+=weights[j]*cw[i]*decoded[i];}require(value==y,"terminal weighted evaluation");}
inline Vec interpolation_weights(const Statement&s){Vec out(s.N),cw=column_weights(s);F step=getRootOfUnity(1+lg(s.N)).inv();for(size_t i=0;i<s.N;i++){Vec v(s.N,F(0));v[i]=F(1);fft(v,lg(s.N),true);F p=1;for(auto&x:v){x*=p;p*=step;}fft(v,lg(s.N),false);for(size_t j=0;j<s.k;j++)out[i]+=cw[j]*v[s.N*j/s.kp];}return out;}
inline Vec masked_aggregate(const Vec&v,const Private&p,const Vec&lambda,size_t offset,size_t N,int rank){require(offset+v.size()<=p.aggregation_masks.size(),"aggregation mask exhaustion");Bytes b;for(size_t i=0;i<v.size();i++)field(b,lambda[rank]*v[i]+p.aggregation_masks[offset+i]);Bytes all=direct_gather(b,N,rank);Vec sum(v.size(),F(0));if(rank==0){Reader r{all};for(size_t party=0;party<N;party++)for(auto&x:sum)x+=r.value();b.clear();fields(b,sum);}direct_broadcast(b,N,rank);Reader r{b};return r.values(v.size());}
inline void prove(const std::string&dir,const std::string&out){Statement s(read(dir+"/statement.bin"));int rank,n;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&n);require(size_t(n)==s.N,"MPI N");// Establish every application link in bounded waves before the online timer.
 for(int offset=1;offset<n;offset++){unsigned char sent=0,received=0;MPI_Sendrecv(&sent,1,MPI_BYTE,(rank+offset)%n,91,&received,1,MPI_BYTE,(rank-offset+n)%n,91,MPI_COMM_WORLD,MPI_STATUS_IGNORE);}MPI_Barrier(MPI_COMM_WORLD);
 Private p=load_private(dir,s,rank);auto used=dir+"/party-"+std::to_string(rank)+".used";int usedfd=open(used.c_str(),O_CREAT|O_EXCL|O_WRONLY,0600);require(usedfd>=0,"private preparation already consumed");close(usedfd);std::vector<Hash> sessions(s.N);MPI_Allgather(p.session.data(),32,MPI_BYTE,sessions.data(),32,MPI_BYTE,MPI_COMM_WORLD);for(auto session:sessions)require(session==p.session,"private session mismatch");Vec weights,cw,lambda;Vec data,code;std::vector<Vec> masks,maskcodes;std::vector<Tree> masktrees;std::vector<Roots> maskroots;
 if(rank==0){printf("{\"event\":\"online_start\"}\n");fflush(stdout);}MPI_Barrier(MPI_COMM_WORLD);auto start=std::chrono::steady_clock::now();online_payload=0;
 weights=row_weights(s);cw=column_weights(s);lambda=interpolation_weights(s);
 // Commitment construction and all authentication serialization are online.
 data=encode_row(p.row);code=encode_coeff(data);
 Tree initial(code);Roots roots=exchange_root(initial.root(),s.N);for(auto&v:p.masks){v=encode_row(v);masks.push_back(v);maskcodes.push_back(encode_coeff(v));masktrees.emplace_back(maskcodes.back());maskroots.push_back(exchange_root(masktrees.back().root(),s.N));}
 Bytes commitment=magic("PAPCM002");hash(commitment,global_root(roots));for(auto&r:maskroots)hash(commitment,global_root(r));Transcript tr(s.bytes);tr.absorb("commitment",commitment);
 Bytes proof=magic("PAPPC002");auto b=root_bytes(roots);proof.insert(proof.end(),b.begin(),b.end());for(auto&r:maskroots){b=root_bytes(r);proof.insert(proof.end(),b.begin(),b.end());}
 std::vector<Vec> codes;std::vector<Tree> trees;F y=s.y;
 for(size_t round=0;round<s.R;round++){
  codes.push_back(code);trees.push_back(std::move(initial));
  F ym=masked_aggregate({dot(masks[round],weights)},p,lambda,4*round,s.N,rank)[0];b.clear();field(b,ym);tr.absorb("mask-evaluation",b);F mix=tr.scalar("mask-challenge");
  for(size_t j=0;j<data.size();j++)data[j]+=mix*masks[round][j];
  quadratic_poly h(0,0,0);for(size_t j=0;j<data.size()/2;j++){F da=data[2*j+1]-data[2*j],db=weights[2*j+1]-weights[2*j];h.a+=da*db;h.b+=da*weights[2*j]+data[2*j]*db;h.c+=data[2*j]*weights[2*j];}
  auto hsum=masked_aggregate({h.a,h.b,h.c},p,lambda,4*round+1,s.N,rank);h=quadratic_poly(hsum[0],hsum[1],hsum[2]);require(h.eval(0)+h.eval(1)==y+mix*ym,"sumcheck prover relation");
  field(proof,ym);b.clear();field(b,h.a);field(b,h.b);field(b,h.c);proof.insert(proof.end(),b.begin(),b.end());tr.absorb("sumcheck",b);F a=tr.scalar("fold-challenge");y=h.eval(a);
  for(size_t j=0;j<code.size();j++)code[j]+=mix*maskcodes[round][j];RS_fold(code,a);fold_vector(data,a);fold_vector(weights,a);
  initial=Tree(code);roots=exchange_root(initial.root(),s.N);b=root_bytes(roots);proof.insert(proof.end(),b.begin(),b.end());tr.absorb("fold-roots",b);
 }
 std::vector<Hash> seeds;auto tails=exchange_tail(code,s,rank,initial.seed,seeds);b=tails_bytes(tails,seeds);proof.insert(proof.end(),b.begin(),b.end());auto q=queries(tr,s);
 Bytes local;for(size_t round=0;round<s.R;round++){auto leaves=query_leaves(q,rank,codes[round].size());open_leaves(local,codes[round],trees[round],leaves);open_leaves(local,maskcodes[round],masktrees[round],leaves);}
 Bytes paths=gather_bytes(local,s.N,rank);if(rank==0)proof.insert(proof.end(),paths.begin(),paths.end());MPI_Barrier(MPI_COMM_WORLD);double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();double maxsecs;MPI_Reduce(&secs,&maxsecs,1,MPI_DOUBLE,MPI_MAX,0,MPI_COMM_WORLD);
 uint64_t total_payload=0;MPI_Reduce(&online_payload,&total_payload,1,MPI_UINT64_T,MPI_SUM,0,MPI_COMM_WORLD);
 if(rank==0){printf("{\"event\":\"online_complete\",\"online_seconds\":%.9f,\"online_payload_bytes\":%llu}\n",maxsecs,(unsigned long long)total_payload);fflush(stdout);write(out+"/statement.bin",s.bytes);write(out+"/commitment.bin",commitment);write(out+"/proof.bin",proof);printf("{\"event\":\"proof_written\",\"online_seconds\":%.9f,\"proof_bytes\":%zu,\"complete_verification\":false}\n",maxsecs,proof.size());}
}
inline void verify(const std::string&dir){auto verify_start=std::chrono::steady_clock::now();auto sb=read(dir+"/statement.bin"),cb=read(dir+"/commitment.bin"),pb=read(dir+"/proof.bin");double read_seconds=elapsed(verify_start);auto algorithm_start=std::chrono::steady_clock::now();Statement s(sb);Reader cr{cb},pr{pb};cr.magic("PAPCM002");pr.magic("PAPPC002");std::vector<Roots> roots{read_roots(pr,s.N)},maskroots;require(global_root(roots[0])==cr.digest(),"initial commitment");for(size_t i=0;i<s.R;i++){maskroots.push_back(read_roots(pr,s.N));require(global_root(maskroots.back())==cr.digest(),"mask commitment");}cr.end();Transcript tr(s.bytes);tr.absorb("commitment",cb);Vec weights=row_weights(s);F y=s.y;Vec challenges,mixes;
 for(size_t i=0;i<s.R;i++){F ym=pr.value();Bytes b;field(b,ym);tr.absorb("mask-evaluation",b);F mix=tr.scalar("mask-challenge");mixes.push_back(mix);F ha=pr.value(),hb=pr.value(),hc=pr.value();quadratic_poly h(ha,hb,hc);require(h.eval(0)+h.eval(1)==y+mix*ym,"sumcheck relation");b.clear();field(b,ha);field(b,hb);field(b,hc);tr.absorb("sumcheck",b);F a=tr.scalar("fold-challenge");challenges.push_back(a);y=h.eval(a);fold_vector(weights,a);roots.push_back(read_roots(pr,s.N));tr.absorb("fold-roots",root_bytes(roots.back()));}
 std::vector<Vec> tails;std::vector<Hash> seeds;for(size_t i=0;i<s.N;i++){seeds.push_back(pr.digest());tails.push_back(pr.values(4*(s.D>>s.R)));}auto b=tails_bytes(tails,seeds);auto q=queries(tr,s);check_terminal(s,tails,roots.back(),seeds,weights,y);
 F twoinv=F(2).inv();for(size_t party=0;party<s.N;party++){size_t count=pr.number();require(count<=pb.size()-pr.pos,"opening chunk length");Bytes chunk(pb.begin()+pr.pos,pb.begin()+pr.pos+count);pr.pos+=count;Reader r{chunk};std::map<size_t,F> expected;
  for(size_t i=0;i<s.R;i++){size_t len=4*s.D>>i;auto leaves=query_leaves(q,party,len);auto values=authenticate(r,len,roots[i][party],leaves);auto masks=authenticate(r,len,maskroots[i][party],leaves);
   auto at=[](const std::map<size_t,std::array<F,4>>&v,size_t j){auto it=v.find(j/4);require(it!=v.end(),"missing opening");return it->second[j%4];};
   for(auto entry:expected)require(at(values,entry.first)==entry.second,"folding consistency");expected.clear();F omega=getRootOfUnity(lg(len)).inv();for(auto query:q)if(query.party==party){size_t lo=query.pos%(len/2);F a=at(values,lo)+mixes[i]*at(masks,lo),b=at(values,lo+len/2)+mixes[i]*at(masks,lo+len/2);F z=twoinv*((F(1)-challenges[i])*(a+b)+F::fastPow(omega,lo)*challenges[i]*(a-b));expected[lo]=z;}
  }
  for(auto entry:expected)require(tails[party][entry.first]==entry.second,"terminal query consistency");r.end();
 }pr.end();printf("{\"accepted\":true,\"public_only\":true,\"proof_bytes\":%zu,\"verify_including_read_seconds\":%.9f,\"read_seconds\":%.9f,\"verification_seconds\":%.9f,\"commitment_bytes\":%zu}\n",pb.size(),elapsed(verify_start),read_seconds,elapsed(algorithm_start),cb.size());
}
inline void forge_terminal_test(const std::string&dir,bool column){Statement s(read(dir+"/statement.bin"));auto b=read(dir+"/proof.bin");size_t last_roots=8+(s.R+1)*s.N*64+s.R*(64+s.N*64)-s.N*64;size_t tail_start=last_roots+s.N*64;size_t d=s.D>>s.R,len=4*d;F omega=getRootOfUnity(lg(len)),colomega=getRootOfUnity(lg(2*s.N));for(size_t party=0;party<(column?s.N:1);party++){size_t start=tail_start+party*(32+16*len);Reader r{b};r.pos=start;Hash seed=r.digest();Vec v=r.values(len);F change=column?F::fastPow(colomega,(2*party+1)*s.kp):F(1);for(size_t i=0;i<len;i++)v[i]+=column?change:F::fastPow(omega,i*d);Tree tree(v,seed);auto h=tree.root();std::copy(h.begin(),h.end(),b.begin()+last_roots+party*64);Bytes values;fields(values,v);std::copy(values.begin(),values.end(),b.begin()+start+32);}write(dir+"/proof.bin",b);}

}
